"""Independent slow reference for the exact envelope / peaks / guard / warmup."""
from math import gcd


def period(T, S, Q):
    m = Q * S
    return m // gcd(m, T)


def hop(profile, upper):
    K = profile['groups']
    jit = profile['jitter_ps']
    return [[(upper[a][b] + upper[b][a]) * 500 + (jit[a] + jit[b]) * 1000
             for b in range(K)] for a in range(K)]


class Ref:
    def __init__(self, profile, fabric):
        self.profile = profile
        self.fab = fabric
        self.n = n = fabric['n']
        self.T = T = fabric['interval_ns']
        self.S = S = fabric['slice_ns']
        self.O = O = fabric['offset_ns']
        self.slices = fabric['slices']
        self.Q = len(self.slices)
        self.P = P = period(T, S, self.Q)
        self.guards = fabric['guards_ns']
        self.reconf = fabric['reconfig_ns']
        v = [[fabric['drift_ppb'][i] for _ in range(P)] for i in range(n)]
        for node, st, en, extra in fabric['heat']:
            for p in range(st, en):
                v[node][p] += extra
        self.v = v
        self.anch = [[False] * P for _ in range(n)]
        for node, st, en in fabric['anchors']:
            for p in range(st, en):
                self.anch[node][p] = True
        self.bl = [set() for _ in fabric['links']]
        for lid, st, en in fabric['blackouts']:
            for p in range(st, en):
                self.bl[lid].add(p)

    def steps(self, p, i, guard, Hm):
        """Yield (phase advance, target node, wbound, wage) lineage steps."""
        P, T, S, O = self.P, self.T, self.S, self.O
        yield (1, i, self.v[i][p] * T, 1)
        if not self.slices:
            return
        nominal = O + p * T
        sl = self.slices[(nominal // S) % self.Q]
        rho = nominal % S
        for l in sl:
            lk = self.fab['links'][l]
            (n0, s0, g0), (n1, s1, g1) = lk['ends']
            for dirn in (0, 1):
                if dirn == 0:
                    src, gs, dst, gd = n0, g0, n1, g1
                    d, q = lk['delay_ns'][0], lk['defer_rounds'][0]
                else:
                    src, gs, dst, gd = n1, g1, n0, g0
                    d, q = lk['delay_ns'][1], lk['defer_rounds'][1]
                if src != i:
                    continue
                if rho < guard or rho + d + guard > S:
                    continue
                r = d // T
                m = d % T
                L = r + (1 if m else 0)
                if any(j % P in self.bl[l] for j in range(p, p + L)):
                    continue
                Delta = L + q
                if m:
                    age = self.v[dst][(p + r) % P] * (T - m)
                    start = p + r + 1
                else:
                    start = p + r
                for j in range(start, start + q):
                    age += self.v[dst][j % P] * T
                yield (Delta, dst, Hm[gs][gd] + age, Delta)

    def envelope(self, upper, guard, hmax):
        """Per-phase-device (bound, age) plus warmup, from an unrolled DP."""
        P, N = self.P, self.n
        Hm = hop(self.profile, upper)
        lab = {}
        for t in range(hmax + 1):
            p = t % P
            for i in range(N):
                if self.anch[i][p]:
                    lab[(t, i)] = (0, 0)
            for i in range(N):
                cur = lab.get((t, i))
                if cur is None:
                    continue
                for (adv, j, wb, wa) in self.steps(p, i, guard, Hm):
                    tt = t + adv
                    if tt > hmax:
                        continue
                    cand = (cur[0] + wb, cur[1] + wa)
                    old = lab.get((tt, j))
                    if old is None or cand < old:
                        lab[(tt, j)] = cand
        B = [[None] * N for _ in range(P)]
        A = [[None] * N for _ in range(P)]
        for p in range(P):
            for i in range(N):
                bestb = None
                bestage = None
                t = p
                while t <= hmax:
                    e = lab.get((t, i))
                    if e is not None:
                        if bestb is None or e[0] < bestb:
                            bestb = e[0]
                            bestage = e[1]
                        elif e[0] == bestb and e[1] < bestage:
                            bestage = e[1]
                    t += P
                B[p][i] = bestb
                A[p][i] = bestage
        # warmup: smallest k with every boundary in cycle k attaining B
        warm = None
        for k in range(0, (hmax + 1) // P + 1):
            good = True
            for t in range(k * P, k * P + P):
                if t > hmax:
                    good = False
                    break
                p = t % P
                for i in range(N):
                    e = lab.get((t, i))
                    if e is None or e[0] != B[p][i]:
                        good = False
                        break
                if not good:
                    break
            if good:
                warm = k
                break
        return B, A, warm, lab

    def solve(self, upper):
        P, N = self.P, self.n
        hmax = 24 * P * N + 64
        out = []
        prev_null = False
        for g in self.guards:
            if prev_null:
                out.append((None, None, None, None))
                continue
            B, A, warm, lab = self.envelope(upper, g, hmax)
            if any(b is None for row in B for b in row):
                out.append((None, None, None, None))
                prev_null = True
                continue
            peak = max(B[p][i] + self.v[i][p] * self.T
                       for p in range(P) for i in range(N))
            safe = peak + self.reconf * 1000 <= g * 1000
            out.append((B, A, peak, warm if safe else None))
        sel = None
        for idx, (B, A, peak, warm) in enumerate(out):
            if B is not None and peak + self.reconf * 1000 <= self.guards[idx] * 1000:
                sel = idx
                break
        return out, sel
